	binary.BigEndian.PutUint32(body, uint32(len(hash)))
	body = append(body, hash...)
	body = append(body, pw...)
	if b, err := workerCall("/bcmp", body); err == nil {
		return string(b) == "1"
	}
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

