func flushLog() {
	logMu.Lock()
	q := logQ
	logQ = nil
	f := logFile
	if len(q) == 0 {
		logMu.Unlock()
		return
	}
	buf := make([]byte, 0, 256*len(q))
	for _, op := range q {
		b, _ := json.Marshal(op)
		buf = append(buf, b...)
		buf = append(buf, '\\n')
	}
	f.Write(buf)
	logMu.Unlock()
}

